"""Expand the catalog: 12 departments x 10 subcategories x 10 products (~1,200), generated by an EIS-hosted LLM.
Base products (data/products_base.json, SKU-0001..0060) are kept as-is; new SKUs start at SKU-0061.
Output: data/products_extra.json and the merged data/products.json."""
import json, re, pathlib, sys, threading
from concurrent.futures import ThreadPoolExecutor, as_completed
from common import call

LLM = ".anthropic-claude-5.5-haiku-completion"
D = pathlib.Path(__file__).parent / "data"
DEPTS = {
 "outdoor & camping gear": ["backpacking tents","sleeping bags","hiking backpacks","camp cookware and stoves","water filters and hydration","headlamps and lanterns","trekking poles","rain shells and outdoor jackets","camping hammocks","climbing accessories"],
 "home espresso & kitchen appliances": ["espresso machines","coffee grinders","pour-over and drip coffee","blenders","air fryers","kitchen knives","cookware sets","stand mixers","tea kettles and tea makers","food storage and meal prep"],
 "running & fitness wearables": ["running shoes","GPS running watches","heart rate monitors and fitness trackers","yoga mats","adjustable dumbbells","resistance bands","foam rollers and recovery tools","hydration vests","indoor cycling trainers","swim gear"],
 "home office & ergonomic furniture": ["ergonomic office chairs","standing desks","monitor arms","mechanical keyboards","ergonomic mice","webcams","desk lamps","office headsets","docking stations","cable management"],
 "smart home & security devices": ["video doorbells","smart locks","smart thermostats","indoor and outdoor security cameras","smart plugs","smoke and CO alarms","smart bulbs","robot vacuums","air purifiers","water leak sensors"],
 "bike components & accessories": ["road bike tires","bike helmets","bike lights","bike locks","bike pedals","bike saddles","floor and mini pumps","panniers and bike bags","cycling apparel","bike computers"],
 "audio & consumer electronics": ["over-ear headphones","wireless earbuds","portable bluetooth speakers","soundbars","turntables","portable power banks","e-readers","tablets","action cameras","consumer drones"],
 "home & garden": ["garden hand tools","gas and charcoal grills","patio furniture","bedding and pillows","area rugs","closet and home storage","indoor and outdoor lighting","cleaning tools","plant care and grow lights","home tool sets"],
 "pet supplies": ["dog beds","pet GPS trackers and smart collars","cat trees","automatic pet feeders","pet grooming tools","dog leashes and harnesses","aquarium equipment","pet travel carriers","dog and cat toys","litter boxes"],
 "baby & kids": ["strollers","car seats","baby monitors","STEM toys","school backpacks","baby bottles and feeding","baby carriers","play mats","kids bikes","lunch boxes"],
 "beauty & personal care": ["electric toothbrushes","electric razors","hair dryers","skincare devices","fragrances","sunscreen","nail care tools","beard trimmers","massage guns","makeup brushes and tools"],
 "travel & luggage": ["carry-on suitcases","duffel bags","packing cubes","travel adapters","neck pillows","passport wallets","luggage scales","tech organizers","insulated water bottles","travel umbrellas"],
}
JOBS = [(d, s) for d, subs in DEPTS.items() for s in subs]
REQ = {"name","brand","category","price","rating","tags","description"}
lock = threading.Lock(); done = 0

def gen(dept, sub, attempt=0):
    prompt = (f"Return ONLY a JSON array of 10 distinct, realistic ecommerce products in the subcategory '{sub}' (department: {dept}). "
              "Use fictional brand names (no real trademarks) and varied price points and ratings. Each object has exactly these keys: "
              '"name" (unique, specific model name), "brand", "category" (use the department name exactly), "price" (number in USD), '
              '"rating" (float 3.0-5.0), "tags" (array of 4 short strings), and "description" (a long, realistic 220-320 word product description '
              "covering features, specs, materials, intended use cases, care and warranty; vary the structure and wording between products).")
    try:
        r = call("POST", f"/_inference/completion/{LLM}", {"input": prompt}, timeout=600)
        txt = r["completion"][0]["result"]
        arr = json.loads(re.search(r"\[.*\]", txt, re.S).group(0))
        ok = [p for p in arr if REQ <= set(p) and len(str(p["description"]).split()) >= 120 and isinstance(p["tags"], list)]
        if len(ok) < 6: raise ValueError(f"only {len(ok)} valid")
        for p in ok: p["category"] = dept; p["subcategory"] = sub
        return ok
    except (Exception, SystemExit) as e:
        if attempt < 3: return gen(dept, sub, attempt + 1)
        print("FAILED", sub, str(e)[:120], flush=True); return []

base = json.loads((D / "products_base.json").read_text())
seen = {p["name"].lower() for p in base}
extra = []
with ThreadPoolExecutor(max_workers=int(sys.argv[1]) if len(sys.argv) > 1 else 6) as ex:
    futs = {ex.submit(gen, d, s): (d, s) for d, s in JOBS}
    for f in as_completed(futs):
        for p in f.result():
            k = p["name"].lower()
            if k not in seen: seen.add(k); extra.append(p)
        done += 1
        print(f"{done}/{len(JOBS)} subcategories, {len(extra)} products", flush=True)
for i, p in enumerate(extra, len(base) + 1): p["sku"] = f"SKU-{i:04d}"
(D / "products_extra.json").write_text(json.dumps(extra, indent=1))
(D / "products.json").write_text(json.dumps(base + extra, indent=1))
print("base", len(base), "extra", len(extra), "total", len(base) + len(extra))
